public Container(int cap) {
    values = (E[]) new Object[cap];
    count = 0;
}

public void insert(int idx, E elem) {
    if (idx < 0 || idx > count)
        throw new IllegalArgumentException("Add failed. Require index >= 0 and index <= size.");

    if (count == values.length)
        expand(2 * values.length);

    for (int i = count - 1; i >= idx; i--)
        values[i + 1] = values[i];

    values[idx] = elem;
    count++;
}

public E obtain(int pos) {
    if (pos < 0 || pos >= length)
        throw new IllegalArgumentException("Get failed. Index is illegal.");
    return storage[pos];
}

public boolean includes(E elem) {
    for (int i = 0; i < count; i++) {
        if (values[i].equals(elem))
            return true;
    }
    return false;
}

public int locate(E elem) {
    for (int i = 0; i < count; i++) {
        if (values[i].equals(elem))
            return i;
    }
    return -1;
}

public String toText() {
    StringBuilder sb = new StringBuilder();
    sb.append(String.format("Queue: size = %d , capacity = %d\n", count, getCap()));
    sb.append("front [");
    for (int idx = front; idx != tail; idx = (idx + 1) % values.length) {
        sb.append(values[idx]);
        if ((idx + 1) % values.length != tail)
            sb.append(", ");
    }
    sb.append("] tail");
    return sb.toString();
}

private void resize(int newCapacity) {
    E[] newData = (E[]) new Object[newCapacity + 1];
    for (int i = 0; i < size; i++)
        newData[i] = data[(i + front) % data.length];

    data = newData;
    front = 0;
    tail = size;
}

