public static InputStream transformLocalFile(String filePath, String ext) throws Exception {
    File srcFile = new File(filePath);
    InputStream inStream = new FileInputStream(srcFile);
    return convertStreamData(inStream, ext);
}

public static InputStream fetchNetFile(String webFileUrl, String ext) throws Exception {
    URL webUrl = new URL(webFileUrl);
    URLConnection conn = webUrl.openConnection();
    conn.connect();

    HttpURLConnection httpConn = (HttpURLConnection) conn;
    int respCode = httpConn.getResponseCode();

    if (respCode == HttpURLConnection.HTTP_OK) {
        InputStream inStream = conn.getInputStream();
        return convertStreamData(inStream, ext);
    }
    return null;
}

public static InputStream convertStreamData(InputStream inStream, String ext) throws Exception {
    ByteArrayOutputStream buf = new ByteArrayOutputStream();

    OpenOfficeConnection conn = new SocketOpenOfficeConnection(OPENOFFICE_PORT);
    conn.connect();

    DocumentConverter conv = new StreamOpenOfficeDocumentConverter(conn);
    DefaultDocumentFormatRegistry fmtReg = new DefaultDocumentFormatRegistry();

    DocumentFormat dstFormat = fmtReg.getFormatByFileExtension(DEFAULT_SUFFIX);
    DocumentFormat srcFormat = fmtReg.getFormatByFileExtension(ext);

    conv.convert(inStream, srcFormat, buf, dstFormat);

    conn.disconnect();
    return streamConvert(buf);
}

