}

public ScheduledTask getEarliestTaskTime(Integer idx) {
    String bucket = taskBuckets.get(idx);
    BoundZSetOperations<Object, Object> zset = getBucket(bucket);
    Set<TypedTuple<Object>> items = zset.rangeWithScores(0, 1);
    if (CollectionUtils.isEmpty(items)) {
        return null;
    }
    TypedTuple<Object> tuple = items.stream().findFirst().get();
    Object data = tuple.getValue();
    if (data instanceof ScheduledTask) {
        return (ScheduledTask) data;
    }
    return null;
}

public void deleteTaskTime(Integer idx, ScheduledTask task) {
    String bucket = taskBuckets.get(idx);
    BoundZSetOperations<Object, Object> zset = getBucket(bucket);
    zset.remove(task);
}

