    BoundListOperations<Object, Object> queueOps = fetchQueue(delayTask.getSubject());
    queueOps.leftPush(delayTask);
}

public DelayTask fetchTask(String subject) {
    BoundListOperations<Object, Object> queueOps = fetchQueue(subject);
    Object obj = queueOps.leftPop();
    if (obj instanceof DelayTask) {
        logger.info("执行队列取出任务:{}", JSON.toJSONString((DelayTask) obj));
        return (DelayTask) obj;
    }
    return null;
}

