public Result<?> checkDup(@RequestBody Map<String, Object> args) {
    if (null == args || args.isEmpty()) {
        return Result.error("参数为空");
    }
    for (Map.Entry<String, Object> item : args.entrySet()) {
        if (StringUtils.hasText(item.getKey())) {
            if (baseService.hasValue(item.getKey(), item.getValue())) {
                return Result.ok(item.getKey() + "字段值重复", 1);
            }
        }
    }
    return Result.ok("无重复值", 0);
}

