public boolean hasPager() {
    if (pageIndex == null || pageIndex <= 0) {
        return false;
    }
    if (pageSize == null || pageSize <= 0) {
        pageSize = Constants.PAGE_SIZE;
    }
    return true;
}

public BaseService() {
    ParameterizedType paramType = (ParameterizedType) getClass().getGenericSuperclass();
    Type tType = paramType.getActualTypeArguments()[0];
    Type idType = paramType.getActualTypeArguments()[1];
    clsT = (Class<T>) tType;
    clsID = (Class<ID>) idType;
}

public Result<List<T>> fetchItems(BasePager pager) {
    Sort ordering = null;
    if (StringUtils.hasText(pager.getSortBy())) {
        ordering = Sort.by(
            Direction.fromOptionalString(pager.getSortDir()).orElse(Direction.ASC),
            pager.getSortBy().split(",")
        );
    }
    PageRequest request = PageRequest.of(pager.getPageNo() - 1, pager.getPageSize(), ordering);
    Page<T> data = baseRepo.findAll(request);
    return null == data 
        ? Result.page(null, pager.getPageNo(), pager.getPageSize(), 0)
        : Result.page(data.getContent(), pager.getPageNo(), pager.getPageSize(), data.getTotalElements());
}

