}

private void buildTree(List<Map<String, Object>> list) {
    if (null == list || list.isEmpty()) {
        return;
    }
    for (Map<String, Object> item : list) {
        if (Objects.nonNull(item.get("childNum")) && 
            Integer.parseInt(item.get("childNum").toString()) > 0) {

            List<Map<String, Object>> children = 
                getTreeById(item.get("treeId").toString(), true);
            buildTree(children);
            item.put("children", children);
        }
    }
}

public boolean checkValue(String field, Object val) {
    Specification<T> spec = new Specification<T>() {

        private static final long serialVersionUID = 1L;

        @Override
        public Predicate toPredicate(Root<T> root,
                                     CriteriaQuery<?> query,
                                     CriteriaBuilder cb) {
            return cb.equal(root.get(field), val);
        }
    };
    return baseRepo.count(spec) > 0;
}

